def preorder_traversal(inorder: str, postorder: str) -> str:
    # Initialize an empty stack
    stack = []

    # Add the root node to the stack
    stack.append(postorder[-1])

    # Loop through the postorder traversal
    for i in range(len(postorder) - 2, -1, -1):
        # If the current node is not in the inorder traversal,
        # it must be a right child
        if postorder[i] not in inorder:
            stack.append(postorder[i])

    # Loop through the inorder traversal
    for char in inorder:
        # If the current character is not in the postorder traversal,
        # it must be a left child
        if char not in postorder:
            stack.append(char)

    # Return the preorder traversal
    return "".join(stack)

