    unique_numbers = set()
    queue = [n]
    while queue:
        number = queue.pop(0)
        for rule in rules:
            digit_x, digit_y = rule
            if digit_x in str(number):
                new_number = str(number).replace(digit_x, digit_y)
                if new_number not in unique_numbers:
                    unique_numbers.add(new_number)
                    queue.append(new_number)
    return len(unique_numbers)

